module Nibble
  class TypeGenerator
    PRELUDE = <<~TS.freeze
      // Generated by `bin/rails nibble:schema:types`. Do not edit.
      import type { NavigationItemBase, NavigationLinkType, NibbleForm } from '@nibble'
      export type EntrySummary = { id: string; type: 'entry'; title: string; uri: string | null; url: string | null; collection: string }
      export type TermSummary = { id: string; type: 'term'; title: string; uri: string | null; url: string | null; taxonomy: string }
      export type AssetValue = { id: string; title: string; filename: string; kind: string; url: string; alt: string | null; width?: number | null; height?: number | null; srcset?: string | null; focal?: { x: number; y: number } | null }
      export type PaginationMeta = { current_page: number; per_page: number; total: number; last_page: number }
      export type Paginated<T> = { data: T[]; meta: PaginationMeta }
      export type ParentSummary = { title: string | null; uri: string | null }
      export interface RecordBase {
        id: number
        uuid: string
        type: 'entry' | 'term'
        blueprint: string
        locale: string
        title: string | null
        slug: string | null
        uri: string | null
        url: string | null
        status: string | null
        published_at: string | null
        updated_at: string | null
        search_snippet?: string
        parent?: ParentSummary | null
      }
    TS

    def self.output(config = Nibble.config) = config.theme_path && config.types_path

    # An unchanged file is left alone: rewriting it would have Vite reload every open page for nothing.
    def self.write!(schema = Nibble.schema, config: Nibble.config)
      output = output(config) or return nil
      types = new(schema, config:).generate
      return output if output.file? && output.read == types

      output.dirname.mkpath
      output.write(types)
      output
    end

    def initialize(schema = Nibble.schema, config: Nibble.config)
      @schema = schema
      @config = config
    end

    def generate
      blocks = [ PRELUDE ]
      (@schema.collections + @schema.taxonomies).each do |parent|
        scope = parent.kind == "collections" ? "collection: '#{parent.handle}'" : "taxonomy: '#{parent.handle}'"
        names = @schema.blueprints_for(parent).map do |item|
          name = "#{pascal(parent.handle)}#{pascal(item.handle)}"
          blocks << interface(name, Blueprint.new(item, schema: @schema).fields, extends: "RecordBase", extra: [ scope ])
          name
        end
        union = "#{pascal(parent.handle)}#{parent.kind == 'collections' ? 'Entry' : 'Term'}"
        blocks << "export type #{union} = #{names.join(' | ')}\n" if names.any? && !names.include?(union)
      end
      @schema.globals.reject { |item| item.handle == Integrations::HANDLE }.each do |item|
        inline = Schema::Item.new(kind: "blueprints", handle: item.handle, parent: item.key, path: item.path, layer: item.layer, data: item["blueprint"])
        blocks << interface("#{pascal(item.handle)}Globals", Blueprint.new(inline, schema: @schema).fields)
      end
      blocks << navigation_types
      blocks << form_values
      blocks << sidecar_props("ViewProps", Views.sidecars(config: @config)) << sidecar_props("LayoutProps", Views.layout_sidecars(config: @config)) if @config.theme_path
      blocks.join("\n")
    end

    private

    def interface(name, fields, extends: nil, extra: [])
      members = extra + fields.select(&:api?).map { |field| "#{field.handle}: #{field.fieldtype.ts_type}" }
      "export interface #{name}#{" extends #{extends}" if extends} {\n#{members.map { |member| "  #{member}" }.join("\n")}\n}\n"
    end

    def navigation_types
      menus = @schema.navigations.map { |item| MenuSchema.new(item, schema: @schema) }
      types = menus.map { |menu| navigation_type(menu) }
      map = menus.map { |menu| "    '#{menu.handle}': #{pascal(menu.handle)}NavigationItem" }
      types << "declare module '@nibble/types' {\n  interface NavigationMenus {\n#{map.join("\n")}\n  }\n}\n"
      types.join("\n")
    end

    def navigation_type(menu)
      name = "#{pascal(menu.handle)}Navigation"
      members = ->(fields) { fields.all.values.select(&:api?).map { |field| "#{field.handle}: #{field.fieldtype.ts_type}" } }
      entry = menu.entry_fields.map do |handle|
        types = menu.entry_field(handle).select(&:api?).map { |field| field.fieldtype.ts_type }.uniq
        "#{handle}: #{types.empty? ? 'unknown' : types.join(' | ')}"
      end
      shared = members.(menu.item_fields)
      link = [ "NavigationLinkType", "string" ]
      none = [ "null", "null" ]
      targets = { "required" => link, "none" => none }
      variants = [ [ "link", link, shared ] ]
      variants << [ "heading", none, shared ] if menu.headings?
      variants << [ "query", none, shared ] if menu.queries.any?
      variants += menu.kinds.map do |kind|
        [ kind.handle, targets.fetch(kind.link, [ "NavigationLinkType | null", "string | null" ]), shared + members.(kind.fields) ]
      end
      lines = variants.map do |kind, (type, url), own|
        "  | (NavigationItemBase<#{name}Item> & { kind: '#{kind}'; type: #{type}; url: #{url}; fields: #{object_type(own)}; entry: #{name}Entry | null })"
      end
      "export type #{name}Entry = #{object_type(entry)}\nexport type #{name}Item =\n#{lines.join("\n")}\n"
    end

    def object_type(members) = members.empty? ? "{}" : "{ #{members.join('; ')} }"

    def form_values
      forms = Forms.all(schema: @schema)
      types = forms.map do |form|
        members = form.fields(schema: @schema).all.values.reject(&:display_only?).map { |field| "#{field.handle}: #{form_value_type(field)}" }
        "export type #{form_values_name(form.handle)} = {#{members.map { |member| " #{member}" }.join(';')} }\n"
      end
      map = forms.map { |form| "  '#{form.handle}': #{form_values_name(form.handle)}" }
      types << "export interface FormValues {\n#{map.join("\n")}\n}\n"
      types.join("\n")
    end

    def form_values_name(handle) = "#{pascal(handle)}FormValues"

    def form_value_type(field)
      case field.type
      when "toggle" then "boolean"
      when "files" then "File[]"
      when "checkboxes" then "(#{option_union(field)})[]"
      when "select" then field.fieldtype.multiple? ? "(#{option_union(field)})[]" : "#{option_union(field)} | ''"
      when "radio", "button_group" then "#{option_union(field)} | ''"
      when "integer", "decimal", "range", "rating", "calculation" then "string | number | null"
      else "string"
      end
    end

    def option_union(field)
      source = Options.for(field)
      return "string" if source.content?

      choices = source.options.map { |option| "'#{option['value'].to_s.gsub(/['\\]/) { |char| "\\#{char}" }}'" }
      choices.empty? ? "string" : choices.join(" | ")
    end

    def sidecar_props(name, sidecars)
      sidecars = sidecars.map do |sidecar|
        props = sidecar.queries.map { |prop, raw| "    #{prop}: #{query_type(Query::Spec.parse(raw, schema: @schema))}" }
        props.unshift("    page: #{page_type(sidecar.page_include, rendered_by(name, sidecar.view))}") if sidecar.page_include.any?
        "  '#{sidecar.view}': {\n#{props.join("\n")}\n  }"
      end
      "export interface #{name} {\n#{sidecars.join("\n")}\n}\n"
    end

    def query_type(spec)
      return "NibbleForm<#{form_values_name(spec.source.handle)}>" if spec.source.form?

      children = spec.include.include?("children") && !spec.source.relation_fields(@schema).key?("children")
      record = record_type(spec, include: spec.include - (children ? %w[children] : []))
      record = picked(record, spec.fields) if spec.fields && !spec.source.search?
      record = "(#{record} & { children: #{child_type(spec)}[] })" if children
      record = "(#{record} & { entries_count: number })" if spec.counts
      spec.paginate ? "Paginated<#{record}>" : "#{record}[]"
    end

    # Children are presented a level down, where includes no longer expand.
    def child_type(spec) = spec.fields ? picked(record_type(spec), spec.fields) : record_type(spec)

    # Only the included fields: a view already types its page and joins this to it.
    def page_type(include, parents)
      fields = parents.flat_map { |parent| @schema.blueprints_for(parent) }
        .flat_map { |item| Blueprint.new(item, schema: @schema).fields.all.values }
      members = include.filter_map do |handle|
        if handle == "children"
          structured = parents.select { |item| item["structure"].is_a?(Hash) }
          next "children: #{structured.empty? ? 'never' : union(structured)}[]"
        end

        types = fields.select { |field| field.handle == handle && field.fieldtype_class&.relationship }.map { |field| included_type(field) }.uniq
        "#{handle}: #{types.join(' | ')}" if types.any?
      end
      object_type(members)
    end

    # The collections and taxonomies whose records a view or layout renders; all of them when none names it.
    def rendered_by(props, name)
      items = @schema.collections + @schema.taxonomies
      found = items.select do |item|
        if props == "LayoutProps" then (item["layout"] || "default") == name
        else item["template"] == name || @schema.blueprints_for(item).any? { |blueprint| blueprint["template"] == name }
        end
      end
      found.empty? ? items : found
    end

    # A record has no parent key: the presenter adds one only when asked, so it can't be picked from the record.
    def picked(record, fields)
      picked = "Pick<#{record}, #{((fields - %w[parent]) | %w[id type title uri url]).map { |field| "'#{field}'" }.join(' | ')}>"
      fields.include?("parent") ? "(#{picked} & { parent: ParentSummary | null })" : picked
    end

    def record_type(spec, include: [])
      source = spec.source
      parents = if source.search?
        definition = Search.indexes(schema: @schema)[source.handle].to_h
        Array(definition["collections"]).filter_map { |handle| @schema.collection(handle) } + Array(definition["taxonomies"]).filter_map { |handle| @schema.taxonomy(handle) }
      else
        [ source.schema_item(@schema) ]
      end
      union(parents, include:)
    end

    def union(parents, include: [])
      names = parents.flat_map { |parent| @schema.blueprints_for(parent).map { |item| expanded("#{pascal(parent.handle)}#{pascal(item.handle)}", item, include) } }
      names.empty? ? "RecordBase" : "(#{names.join(' | ')})"
    end

    # An included field holds whole records where the blueprint's own type has summaries.
    def expanded(name, item, include)
      return name if include.empty?

      fields = Blueprint.new(item, schema: @schema).fields
      handles = include.select { |handle| fields.get(handle)&.fieldtype_class&.relationship }
      return name if handles.empty?

      "Omit<#{name}, #{handles.map { |handle| "'#{handle}'" }.join(' | ')}> & #{object_type(handles.map { |handle| "#{handle}: #{included_type(fields.get(handle))}" })}"
    end

    def included_type(field)
      fieldtype = field.fieldtype
      parents = case fieldtype
      when Fieldtypes::Entries then targets(@schema.collections, fieldtype.config("collections"))
      when Fieldtypes::Terms then targets(@schema.taxonomies, fieldtype.config("taxonomies"))
      else return fieldtype.ts_type
      end
      fieldtype.single? ? "#{union(parents)} | null" : "#{union(parents)}[]"
    end

    def targets(items, handles) = Array(handles).compact_blank.empty? ? items : items.select { |item| Array(handles).include?(item.handle) }

    def pascal(handle) = handle.to_s.delete_prefix("nibble::").camelize
  end
end
